param(
    [string]$Project = "C:\Proyectos\pdfprivado-pro",
    [string]$AuditRoot = ""
)

$ErrorActionPreference = "Stop"
$Downloads = Join-Path $env:USERPROFILE "Downloads"

if (-not (Test-Path -LiteralPath $Project)) {
    throw "No existe el proyecto: $Project"
}

if (-not $AuditRoot) {
    $AuditRoot = Get-ChildItem `
        -LiteralPath $Downloads `
        -Directory |
        Where-Object { $_.Name -like "PDFPrivado-auditoria-estructural-word-v23-*" } |
        Sort-Object LastWriteTime -Descending |
        Select-Object -First 1 -ExpandProperty FullName
}

if (-not $AuditRoot -or -not (Test-Path -LiteralPath $AuditRoot)) {
    throw "No se encontro la auditoria estructural v23."
}

$PythonCommand = Get-Command python.exe -ErrorAction SilentlyContinue
if (-not $PythonCommand) {
    $PythonCommand = Get-Command python -ErrorAction SilentlyContinue
}
if (-not $PythonCommand) {
    throw "No se encontro Python."
}

$PythonExe = $PythonCommand.Source
if (-not $PythonExe) { $PythonExe = $PythonCommand.Path }

$Stamp = Get-Date -Format "yyyyMMdd-HHmmss"
$Driver = Join-Path $Downloads "PDFPrivado-S1B7-T5-driver-$Stamp.py"

[System.IO.File]::WriteAllBytes(
    $Driver,
    [Convert]::FromBase64String("")
)

Write-Host "============================================================" -ForegroundColor Cyan
Write-Host " PDFPRIVADO PRO - S1B7-T5 HYBRID TABLE SHELL FULL206" -ForegroundColor Cyan
Write-Host "============================================================" -ForegroundColor Cyan
Write-Host ""
Write-Host "T4-v3 queda cerrado como diagnostico causal." -ForegroundColor Green
Write-Host "T5 reutiliza SOLO la rama SHELL positiva; no repite T4." -ForegroundColor Green
Write-Host "Tabla real + texto v23 intacto en Table-only." -ForegroundColor Yellow
Write-Host "Mixed conserva R3; Form-only/resto conserva v23." -ForegroundColor Yellow
Write-Host "No rerenderiza R3/R3R/R3P. No commit. No tag. No promocion." -ForegroundColor Green
Write-Host ""

& $PythonExe `
    $Driver `
    --project $Project `
    --audit-root $AuditRoot `
    --downloads $Downloads

$ExitCode = $LASTEXITCODE

Write-Host ""
if ($ExitCode -eq 0) {
    Write-Host "S1B7-T5 PASS." -ForegroundColor Green
    Write-Host "T5 queda aplicado solo como base de trabajo; NO es promocion v24." -ForegroundColor Green
} elseif ($ExitCode -eq 2) {
    Write-Host "S1B7-T5 FAIL por metricas; R3P restaurado." -ForegroundColor Yellow
} else {
    Write-Host "S1B7-T5 fallo tecnicamente; R3P restaurado." -ForegroundColor Red
}

Write-Host "No se ha hecho commit, tag ni promocion oficial." -ForegroundColor Green
exit $ExitCode
